  1→/**
  2→ * report-pipeline.ts — 报告生成三段管线可插拔框架契约（DR-44 需求 A1）
  3→ *
  4→ * 三段管线（DR-44 §2.1）：
  5→ *   explore LLM → findings.json
  6→ *   narrative LLM → narrative.json（数据源无关，框架固定提供）
  7→ *   render 纯代码 → report.html（数据源无关，框架固定提供）
  8→ *
  9→ * 每个数据源（unity/perfetto/simpleperf）只实现 explore 侧 + 报告章节模板路径，
 10→ * narrative/render 不暴露在接口里——机制上保证数据源无法绕过 LLM。
 11→ *
 12→ * 参照实现：unity 阶段（explore-service.ts + narrative-prompt.txt + render-html.ts）。
 13→ * 本工单只建框架，unity 接入 registry 是后续工单的事。
 14→ */
 15→
 16→import type Database from 'better-sqlite3';
 17→
 18→// ─────────────────────── ToolRegistry（数据源特定工具集） ───────────────────────
 19→
 20→/**
 21→ * 单个 Prism 查询工具的执行器签名（对齐 tools.cli.ts 的 ToolRunner）。
 22→ * 纯函数：(db, args) → { data, provenance } | unknown。
 23→ */
 24→export type ToolRunner = (
 25→  db: Database.Database | null,
 26→  args: Record<string, unknown>,
 27→) => unknown;
 28→
 29→/**
 30→ * 数据源特定的工具集注册表：工具名 → 执行器。
 31→ * 每个数据源在 explore 阶段只允许调用自己注册的工具（数据源无关的 Bash/Read/Write
 32→ * 等通用工具由 explore-service 的 allowedTools 控制，不在这里）。
 33→ */
 34→export type ToolRegistry = Record<string, ToolRunner>;
 35→
 36→// ─────────────────────── ReportPipeline 契约 ───────────────────────
 37→
 38→/**
 39→ * 数据源接入报告生成三段管线的契约。
 40→ * 每个数据源（unity/perfetto/simpleperf）实现一份，注册到 pipeline registry。
 41→ *
 42→ * 三段管线（DR-44）：
 43→ *   explore LLM → findings.json
 44→ *   narrative LLM → narrative.json（数据源无关，框架提供）
 45→ *   render 纯代码 → report.html（数据源无关，框架提供）
 46→ *
 47→ * 数据源只实现 explore 侧 + 报告模板路径，narrative/render 不写。
 48→ */
 49→export interface ReportPipeline {
 50→  /** 数据源标识（如 'unity' / 'perfetto' / 'simpleperf'） */
 51→  source: string;
 52→
 53→  // ── 数据源特定：explore 阶段 ──
 54→  /** explore prompt 路径（如 'prompts/explore-prompt.txt' for unity, 'prompts/perfetto-explore-prompt.txt' for perfetto） */
 55→  explorePromptPath: string;
 56→  /** explore 阶段可用的工具集注册（数据源特定工具） */
 57→  exploreTools: ToolRegistry;
 58→
 59→  // ── 数据源特定：报告章节模板（注入 narrative-prompt 的 {{REPORT_TEMPLATE}}） ──
 60→  /** 报告章节模板路径（如 'prompts/report-templates/perfetto-multi-state.txt'）。null = 用默认骨架 */
 61→  reportTemplatePath: string | null;
 62→
 63→  // ── 数据源无关：narrative 阶段（框架固定提供，数据源不写） ──
 64→  // narrativePromptPath 固定为 'prompts/narrative-prompt.txt'，不暴露在接口里
 65→
 66→  // ── 数据源无关：渲染阶段（框架固定提供，数据源不写） ──
 67→  // renderHtml 固定为 render-html.ts，不暴露在接口里
 68→}
 69→
 70→// ─────────────────────── PipelineRegistry ───────────────────────
 71→
 72→/** 数据源 pipeline 注册表 */
 73→export interface PipelineRegistry {
 74→  get(source: string): ReportPipeline | undefined;
 75→  register(pipeline: ReportPipeline): void;
 76→  list(): string[];
 77→}
 78→
 79→/**
 80→ * 默认的 PipelineRegistry 实现（Map-based）。
 81→ * 用 getDefaultRegistry() 拿单例，或 new DefaultPipelineRegistry() 自建实例。
 82→ */
 83→export class DefaultPipelineRegistry implements PipelineRegistry {
 84→  private readonly pipelines = new Map<string, ReportPipeline>();
 85→
 86→  get(source: string): ReportPipeline | undefined {
 87→    return this.pipelines.get(source);
 88→  }
 89→
 90→  register(pipeline: ReportPipeline): void {
 91→    this.pipelines.set(pipeline.source, pipeline);
 92→  }
 93→
 94→  list(): string[] {
 95→    return Array.from(this.pipelines.keys());
 96→  }
 97→}
 98→
 99→// ─────────────────────── 默认 registry 单例 + 工厂 ───────────────────────
100→
101→let defaultRegistry: PipelineRegistry | null = null;
102→
103→/** 获取进程级默认 registry 单例。首次调用时惰性创建。 */
104→export function getDefaultRegistry(): PipelineRegistry {
105→  if (defaultRegistry === null) {
106→    defaultRegistry = new DefaultPipelineRegistry();
107→  }
108→  return defaultRegistry;
109→}
110→
111→/**
112→ * 工厂函数：按数据源标识从默认 registry 取 pipeline。
113→ * 未注册时抛错（数据源接入前必须先 register）。
114→ */
115→export function getDefaultPipeline(source: string): ReportPipeline {
116→  const registry = getDefaultRegistry();
117→  const pipeline = registry.get(source);
118→  if (!pipeline) {
119→    throw new Error(
120→      `getDefaultPipeline: data source "${source}" not registered. ` +
121→        `Registered sources: [${registry.list().join(', ') || 'none'}]. ` +
122→        `Call registry.register(...) before requesting a pipeline (DR-44 A1).`,
123→    );
124→  }
125→  return pipeline;
126→}
127→

  1→/**
  2→ * explore-service.ts — Prism Phase-A exploration pipeline (task B4)
  3→ *
  4→ * Spawns the LLM CLI with the explore-prompt, records a ledger of every
  5→ * tool_use / tool_result seen in the stream-json output, then verifies
  6→ * each Finding's evidence against the real calls in that ledger.
  7→ *
  8→ * Key principle (F1): every number in a Finding must trace back to a
  9→ * real tool call; verifyFindings detects fabricated evidence.
 10→ */
 11→
 12→import crypto from 'crypto';
 13→import fs from 'fs';
 14→import path from 'path';
 15→import { spawn } from 'child_process';
 16→import { fileURLToPath } from 'url';
 17→import { resolveCliExecutable, spawnCliProcess, cliUnavailableHint } from '../utils/cli-resolver.js';
 18→import { getConfig } from '../utils/config.js';
 19→import { appendMemory, loadMemory, type MemoryCategory } from './prism-memory.js';
 20→import type { Finding, DataRequest, ExploreResult } from './types.js';
 21→
 22→/** Categories injected at explore startup (M3-B). Adjust here, not inline in formatters. */
 23→export const MEMORY_INJECTION_CATEGORIES: MemoryCategory[] = [
 24→  'priors',
 25→  'knowledge',
 26→  'lessons',
 27→  'capabilities',
 28→];
 29→
 30→/** M3-C: persist run DataRequests into capabilities/ at explore end (default on). */
 31→export const DATA_REQUEST_MEMORY_PERSIST_ENABLED = true;
 32→
 33→/** Max characters for the {{MEMORY_INJECTION}} block (~7KB). */
 34→export const MEMORY_INJECTION_MAX_CHARS = 7000;
 35→
 36→// ─────────────────────────────────────────────
 37→// M3-B: memory injection for explore prompt
 38→// ─────────────────────────────────────────────
 39→
 40→export interface FormatMemoryForPromptOptions {
 41→  /** Override memory root (tests). */
 42→  root?: string;
 43→}
 44→
 45→/** Load persistent brain entries and format as compact reference text for the explore prompt. */
 46→export function formatMemoryForPrompt(opts?: FormatMemoryForPromptOptions): string {
 47→  const { byCategory } = loadMemory({
 48→    categories: MEMORY_INJECTION_CATEGORIES,
 49→    root: opts?.root,
 50→  });
 51→
 52→  // Per-category budget so a large category (e.g. 79 priors) can't starve
 53→  // later categories (e.g. freshly-sedimented capabilities). Split the total
 54→  // budget across categories that actually have entries.
 55→  const activeCats = MEMORY_INJECTION_CATEGORIES.filter((c) => byCategory[c]?.length);
 56→  if (activeCats.length === 0) return '';
 57→  const perCatBudget = Math.floor(MEMORY_INJECTION_MAX_CHARS / activeCats.length);
 58→
 59→  const blocks: string[] = [];
 60→
 61→  for (const cat of activeCats) {
 62→    const catEntries = byCategory[cat]!;
 63→    const catLines: string[] = [`## ${cat} (${catEntries.length})`];
 64→    let catChars = catLines[0].length + 1;
 65→    let catTruncated = false;
 66→    let shown = 0;
 67→
 68→    for (const entry of catEntries) {
 69→      const title = entry.title ? String(entry.title) : entry.id;
 70→      const compact = entry.content.replace(/\s+/g, ' ').trim();
 71→      const summary = compact.length > 280 ? `${compact.slice(0, 277)}...` : compact;
 72→      const line = `- [${title}] ${summary}`;
 73→
 74→      if (catChars + line.length + 1 > perCatBudget) {
 75→        catTruncated = true;
 76→        break;
 77→      }
 78→      catLines.push(line);
 79→      catChars += line.length + 1;
 80→      shown++;
 81→    }
 82→
 83→    if (catTruncated) {
 84→      catLines.push(`...(${cat}: showing ${shown}/${catEntries.length}, budget-capped)`);
 85→    }
 86→    blocks.push(catLines.join('\n'));
 87→  }
 88→
 89→  return blocks.join('\n\n').trimEnd();
 90→}
 91→
 92→// ─────────────────────────────────────────────
 93→// M3-C: run-end DataRequest sedimentation
 94→// ─────────────────────────────────────────────
 95→
 96→function normalizeForStableId(text: string): string {
 97→  return text.replace(/\s+/g, ' ').trim().toLowerCase();
 98→}
 99→
100→/**
101→ * Extract semantic fields from a DataRequest, tolerant to schema drift.
102→ * The typed shape is want/rationale/..., but real LLM-written data-requests.json
103→ * uses id/topic/description/reasonMissing/impactOnFindings. Support both.
104→ */
105→function extractDataRequestFields(dr: DataRequest): {
106→  title: string;
107→  body: string;
108→  idParts: string[];
109→} {
110→  const r = dr as unknown as Record<string, unknown>;
111→  const s = (v: unknown): string => (typeof v === 'string' ? v : '');
112→
113→  // Title: prefer real-schema topic, fallback typed want, then id.
114→  const title = s(r.topic) || s(r.want) || s(r.id) || '(untitled data request)';
115→
116→  // Body lines: include whichever fields are present (both schemas).
117→  const lines: string[] = [];
118→  const push = (label: string, v: unknown) => {
119→    const val = s(v);
120→    if (val) lines.push(`${label}: ${val}`);
121→  };
122→  push('Topic', r.topic);
123→  push('Want', r.want);
124→  push('Description', r.description);
125→  push('Rationale', r.rationale);
126→  push('ReasonMissing', r.reasonMissing);
127→  push('ImpactOnFindings', r.impactOnFindings);
128→  push('Axis', r.suspectedAxis);
129→  push('ClosestTool', r.closestExistingTool);
130→  const body = lines.length > 0 ? lines.join('\n') : title;
131→
132→  // Stable-id parts: semantic content across both schemas (never the volatile LLM id).
133→  const idParts = [
134→    s(r.topic),
135→    s(r.want),
136→    s(r.description),
137→    s(r.rationale),
138→    s(r.reasonMissing),
139→    s(r.suspectedAxis),
140→    s(r.closestExistingTool),
141→  ];
142→  return { title, body, idParts };
143→}
144→
145→/** Derive stable id from semantic fields (not LLM-provided id). Same content → same id → overwrite. */
146→export function deriveDataRequestStableId(dr: DataRequest): string {
147→  const { idParts } = extractDataRequestFields(dr);
148→  const payload = idParts.map(normalizeForStableId).join('|');
149→  const hash = crypto.createHash('sha256').update(payload).digest('hex').slice(0, 16);
150→  return `dr-${hash}`;
151→}
152→
153→function formatDataRequestContent(dr: DataRequest): string {
154→  return extractDataRequestFields(dr).body;
155→}
156→
157→/** Append run DataRequests to capabilities/ (incremental; same id overwrites, never clears). */
158→export function persistDataRequestsToMemory(
159→  dataRequests: DataRequest[],
160→  opts?: { runId?: string; root?: string; enabled?: boolean },
161→): number {
162→  const enabled = opts?.enabled ?? DATA_REQUEST_MEMORY_PERSIST_ENABLED;
163→  if (!enabled || dataRequests.length === 0) {
164→    return 0;
165→  }
166→
167→  const source = opts?.runId ?? 'explore-datarequest';
168→  let count = 0;
169→
170→  for (const dr of dataRequests) {
171→    const { title } = extractDataRequestFields(dr);
172→    try {
173→      const id = deriveDataRequestStableId(dr);
174→      appendMemory(
175→        'capabilities',
176→        {
177→          id,
178→          title,
179→          content: formatDataRequestContent(dr),
180→          source,
181→        },
182→        { root: opts?.root },
183→      );
184→      count++;
185→    } catch (e) {
186→      console.warn(
187→        `[explore] persist DataRequest failed (${title.slice(0, 80)}): ${(e as Error).message}`,
188→      );
189→    }
190→  }
191→
192→  return count;
193→}
194→
195→// ─────────────────────────────────────────────
196→// Public types
197→// ─────────────────────────────────────────────
198→
199→/** One entry in the recorded ledger of tool_use / tool_result pairs. */
200→export interface LedgerEntry {
201→  /** 1-based sequence number across all tool_use events */
202→  seq: number;
203→  /** Tool name from the LLM stream-json (e.g. 'Bash', 'Read', 'Write') */
204→  name: string;
205→  /** Raw tool input block as emitted by the CLI */
206→  input: Record<string, unknown>;
207→  /** Text output from the matching tool_result content block (or '' if unmatched yet) */
208→  resultText: string;
209→}
210→
211→/** One evidence item annotated with verification outcome */
212→export interface AnnotatedEvidence {
213→  tool: string;
214→  args: Record<string, unknown>;
215→  resultDigest: unknown;
216→  runId?: string;
217→  // Verification annotations (added by verifyFindings)
218→  verified: boolean;
219→  /** Which ledger seq matched (for audit trail) */
220→  matchedLedgerSeq?: number;
221→  /** Whether the digest numbers were spot-checked against real result */
222→  digestChecked: boolean;
223→  /** Reason if not verified */
224→  notVerifiedReason?: string;
225→}
226→
227→export interface VerificationSummary {
228→  totalFindings: number;
229→  totalEvidence: number;
230→  verifiedEvidence: number;
231→  unverifiedEvidence: number;
232→  findingsWithAllEvidenceVerified: number;
233→  /** Findings where NO evidence matched the ledger — likely fabrication. */
234→  suspects: Array<{ findingId: string; reason: string }>;
235→  /** Findings with SOME evidence verified but some unmatched — partial gap, not fabrication (DR-21). */
236→  partiallyVerified?: Array<{ findingId: string; reason: string }>;
237→}
238→
239→/** Finding with evidence items annotated by verifyFindings */
240→export type AnnotatedFinding = Omit<Finding, 'evidence'> & { evidence: AnnotatedEvidence[] };
241→
242→export interface ExploreRunResult extends ExploreResult {
243→  success: boolean;
244→  error?: string;
245→  ledgerPath: string;
246→  findingsPath: string;
247→  verification: VerificationSummary;
248→  annotatedFindings?: AnnotatedFinding[];
249→  /** F8 overall verdict (from verdict.json), or null if not written. */
250→  verdict?: Record<string, unknown> | null;
251→}
252→
253→/** Options for runPrismExplore */
254→export interface RunPrismExploreOpts {
255→  runId?: string;
256→  outputDir?: string;
257→  cliProvider?: 'codebuddy' | 'claude';
258→  timeoutMs?: number;
259→  /** F8 判定基准：帧预算 ms/帧。默认取 aoe-watch-spec deviceTier 默认 16.67 (60fps)。 */
260→  frameBudgetMs?: number;
261→}
262→
263→// ─────────────────────────────────────────────
264→// Helpers
265→// ─────────────────────────────────────────────
266→
267→/** ESM-safe __dirname equivalent */
268→const __filename = fileURLToPath(import.meta.url);
269→const __dirname = path.dirname(__filename);
270→
271→/** Convert Windows backslash path to POSIX forward-slash path */
272→function toPosix(p: string): string {
273→  return p.replace(/\\/g, '/');
274→}
275→
276→// NOTE: prompt is piped via stdin (see spawn below), NOT passed as `-p` arg.
277→// Windows .cmd wrappers truncate long multi-line prompts passed as positional
278→// args; `-p` with no value tells codebuddy/claude to read the prompt from stdin.
279→const CLI_PROVIDERS: Record<string, (prompt: string) => string[]> = {
280→  codebuddy: (_prompt) => [
281→    '-p',
282→    '--output-format', 'stream-json',
283→    '-y',
284→    '--allowedTools', 'Bash,Read,Write,Glob,Grep',
285→  ],
286→  claude: (_prompt) => [
287→    '-p',
288→    '--output-format', 'stream-json',
289→    '--allowedTools', 'Bash,Read,Write,Glob,Grep',
290→  ],
291→};
292→
293→/**
294→ * Parse the command string inside a Bash tool_use input to extract
295→ * a Prism tools.cli.ts invocation, returning { toolName, argsJson }.
296→ * Returns null if this Bash call is not a tools.cli.ts invocation.
297→ */
298→function parseToolsCliCall(bashCommand: string): { toolName: string; argsJson: string } | null {
299→  // Matches: ... tools.cli.ts <toolName> '<jsonArgs>'
300→  // The JSON args may use single-quotes (shell) or be absent
301→  const re = /tools\.cli\.ts\s+(\w+)\s+'([^']+)'/;
302→  const m = bashCommand.match(re);
303→  if (m) return { toolName: m[1], argsJson: m[2] };
304→
305→  // Also handle: tools.cli.ts <toolName> '<jsonArgs>' with double-quotes
306→  const re2 = /tools\.cli\.ts\s+(\w+)\s+"([^"]+)"/;
307→  const m2 = bashCommand.match(re2);
308→  if (m2) return { toolName: m2[1], argsJson: m2[2] };
309→
310→  // Or no args: tools.cli.ts <toolName>
311→  const re3 = /tools\.cli\.ts\s+(\w+)\s*$/;
312→  const m3 = bashCommand.match(re3);
313→  if (m3) return { toolName: m3[1], argsJson: '{}' };
314→
315→  return null;
316→}
317→
318→/**
319→ * Parse a `tools.cli.ts batch '[{tool,args},...]'` command into its item list.
320→ * Returns null if this is not a batch call.
321→ */
322→function parseBatchCall(bashCommand: string): Array<{ tool: string; args?: Record<string, unknown> }> | null {
323→  const re = /tools\.cli\.ts\s+batch\s+'([\s\S]+?)'(?:\s|$|>)/;
324→  const re2 = /tools\.cli\.ts\s+batch\s+"([\s\S]+?)"(?:\s|$|>)/;
325→  const m = bashCommand.match(re) ?? bashCommand.match(re2);
326→  if (!m) return null;
327→  try {
328→    const arr = JSON.parse(m[1]);
329→    if (!Array.isArray(arr)) return null;
330→    return arr.map((x: { tool: string; args?: Record<string, unknown> }) => ({ tool: x.tool, args: x.args }));
331→  } catch {
332→    return null;
333→  }
334→}
335→
336→/**
337→ * Extract the JSON array printed by a batch invocation from resultText.
338→ * The batch CLI prints `[{tool,args,ok,result},...]`. Returns the array or null.
339→ */
340→function extractBatchResults(text: string): unknown[] | null {
341→  if (!text) return null;
342→  const idx = text.indexOf('[');
343→  if (idx < 0) return null;
344→  let depth = 0, end = -1;
345→  for (let k = idx; k < text.length; k++) {
346→    if (text[k] === '[') depth++;
347→    else if (text[k] === ']') { depth--; if (depth === 0) { end = k + 1; break; } }
348→  }
349→  if (end < 0) return null;
350→  try {
351→    const arr = JSON.parse(text.slice(idx, end));
352→    return Array.isArray(arr) ? arr : null;
353→  } catch {
354→    return null;
355→  }
356→}
357→
358→/**
359→ * Extract the JSON result from a resultText that may contain leading
360→ * log lines (e.g. "[warn] ...") before the actual JSON object.
361→ * Returns the parsed object or null on failure.
362→ */
363→function extractJsonFromResultText(text: string): Record<string, unknown> | null {
364→  // Find the first '{' that starts a JSON object
365→  const idx = text.indexOf('{');
366→  if (idx < 0) return null;
367→  try {
368→    return JSON.parse(text.slice(idx)) as Record<string, unknown>;
369→  } catch {
370→    // Try each line
371→    for (const line of text.split('\n')) {
372→      const trimmed = line.trim();
373→      if (trimmed.startsWith('{')) {
374→        try {
375→          return JSON.parse(trimmed) as Record<string, unknown>;
376→        } catch { /* continue */ }
377→      }
378→    }
379→    return null;
380→  }
381→}
382→
383→/**
384→ * Subset-match (RELAXED — see PRISM-RATIONALE DR-21): the goal is to catch
385→ * FABRICATION (no such call was ever made), not to punish the LLM for imprecise
386→ * argument recall (abbreviated thread names, slightly-off thresholds, extra keys).
387→ * Relaxations:
388→ *  - runId ignored (always default-injected).
389→ *  - thread names normalized: "1:Main Thread" ≈ "Main Thread" (strip leading "N:").
390→ *  - numeric values matched within 5% relative tolerance (or ±0.5 absolute).
391→ *  - a key present in evidence but ABSENT in the ledger args is NOT a hard fail
392→ *    (the LLM may over-specify an optional/default param) — it's tolerated.
393→ *  - core identity keys (markerName / rootMarker / frameIndex) must still match
394→ *    (loosely) when present in BOTH, else it's a different call.
395→ */
396→function normalizeThread(v: unknown): unknown {
397→  if (typeof v !== 'string') return v;
398→  // "1:Main Thread" -> "main thread"; also collapse case/space
399→  return v.replace(/^\d+:/, '').trim().toLowerCase();
400→}
401→
402→function looseValueMatch(a: unknown, b: unknown): boolean {
403→  if (typeof a === 'number' && typeof b === 'number') {
404→    const diff = Math.abs(a - b);
405→    if (diff <= 0.5) return true;
406→    const rel = diff / Math.max(Math.abs(a), Math.abs(b), 1e-9);
407→    return rel <= 0.05;
408→  }
409→  return JSON.stringify(a) === JSON.stringify(b);
410→}
411→
412→function argsSubsetMatch(
413→  evidenceArgs: Record<string, unknown>,
414→  ledgerArgs: Record<string, unknown>,
415→): boolean {
416→  const IGNORE_KEYS = new Set(['runId', 'thread', 'topN', 'maxDepth', 'minPct', 'metric', 'sortBy', 'excludeWaits', 'minSpikeRatio', 'fanoutThreshold', 'minTotalMsPerFrame']);
417→  const THREAD_KEYS = new Set(['thread']);
418→  // Identity keys: if BOTH sides have them, they must match (loosely). These pin
419→  // the call to the same target so we don't match an unrelated call.
420→  const IDENTITY_KEYS = ['markerName', 'rootMarker', 'frameIndex'];
421→
422→  for (const idk of IDENTITY_KEYS) {
423→    if (idk in evidenceArgs && idk in ledgerArgs) {
424→      let ev = evidenceArgs[idk], lv = ledgerArgs[idk];
425→      if (!looseValueMatch(ev, lv)) return false;
426→    }
427→  }
428→  for (const [k, v] of Object.entries(evidenceArgs)) {
429→    if (IGNORE_KEYS.has(k)) continue;
430→    if (IDENTITY_KEYS.includes(k)) continue; // already handled
431→    if (!(k in ledgerArgs)) continue;         // over-specified optional key — tolerate
432→    let ev: unknown = v, lv: unknown = ledgerArgs[k];
433→    if (THREAD_KEYS.has(k)) { ev = normalizeThread(ev); lv = normalizeThread(lv); }
434→    if (!looseValueMatch(ev, lv)) return false;
435→  }
436→  return true;
437→}
438→
439→/**
440→ * Best-effort check that numeric values in resultDigest appear (approximately)
441→ * in the real result JSON.
442→ * "Approximately" = within 1% relative tolerance for floats ≥ 1.
443→ * Returns { checked: boolean; ok: boolean }.
444→ */
445→function spotCheckDigest(
446→  resultDigest: unknown,
447→  realResultJson: Record<string, unknown>,
448→): { checked: boolean; ok: boolean } {
449→  if (typeof resultDigest !== 'object' || resultDigest === null) {
450→    return { checked: false, ok: false };
451→  }
452→  const flatReal = flattenNumbers(realResultJson);
453→  const digestEntries = Object.entries(resultDigest as Record<string, unknown>)
454→    .filter(([, v]) => typeof v === 'number') as Array<[string, number]>;
455→
456→  if (digestEntries.length === 0) return { checked: false, ok: false };
457→
458→  let mismatches = 0;
459→  for (const [, dv] of digestEntries) {
460→    // Check whether dv appears in the flat real numbers (within 1% or exact)
461→    const found = flatReal.some(rv => {
462→      if (rv === dv) return true;
463→      if (Math.abs(dv) < 0.01 && Math.abs(rv) < 0.01) return true; // near-zero
464→      const rel = Math.abs(rv - dv) / Math.max(Math.abs(dv), 0.001);
465→      return rel < 0.02; // 2% tolerance
466→    });
467→    if (!found) mismatches++;
468→  }
469→
470→  return {
471→    checked: true,
472→    ok: mismatches === 0,
473→  };
474→}
475→
476→function flattenNumbers(obj: unknown, depth = 0): number[] {
477→  if (depth > 5) return [];
478→  if (typeof obj === 'number') return [obj];
479→  if (Array.isArray(obj)) return obj.flatMap(v => flattenNumbers(v, depth + 1));
480→  if (typeof obj === 'object' && obj !== null) {
481→    return Object.values(obj).flatMap(v => flattenNumbers(v, depth + 1));
482→  }
483→  return [];
484→}
