486→// ─────────────────────────────────────────────
487→// verifyFindings — the core audit logic
488→// ─────────────────────────────────────────────
489→
490→/**
491→ * For each Finding's evidence ToolCall, check whether the ledger
492→ * contains a matching real call (same prism tool name + matching args subset).
493→ * Annotates findings in place; returns a VerificationSummary.
494→ */
495→export function verifyFindings(
496→  findings: Finding[],
497→  ledger: LedgerEntry[],
498→): {
499→  annotated: AnnotatedFinding[];
500→  summary: VerificationSummary;
501→} {
502→  // Build a map from Prism tool name → ledger entries for quick lookup
503→  // Each ledger entry whose Bash command calls tools.cli.ts is indexed by toolName
504→  type PrismCall = {
505→    seq: number;
506→    toolName: string;
507→    parsedArgs: Record<string, unknown>;
508→    resultJson: Record<string, unknown> | null;
509→  };
510→
511→  const prismCalls: PrismCall[] = [];
512→  for (const entry of ledger) {
513→    if (entry.name !== 'Bash') continue;
514→    const cmd = (entry.input as { command?: string }).command ?? '';
515→
516→    // Case 1: batch call — tools.cli.ts batch '[{tool,args},...]'
517→    // Result is a JSON array [{tool,args,ok,result},...] in the same order.
518→    const batchItems = parseBatchCall(cmd);
519→    if (batchItems) {
520→      const batchResults = extractBatchResults(entry.resultText); // array or null
521→      batchItems.forEach((item, i) => {
522→        const sub = Array.isArray(batchResults) ? batchResults[i] : null;
523→        // sub.result is the tool's { data, provenance }; unwrap to match single-call shape
524→        const resultJson = (sub && typeof sub === 'object' && 'result' in sub)
525→          ? ((sub as { result?: unknown }).result as Record<string, unknown> | null)
526→          : null;
527→        prismCalls.push({
528→          seq: entry.seq,
529→          toolName: item.tool,
530→          parsedArgs: item.args ?? {},
531→          resultJson,
532→        });
533→      });
534→      continue;
535→    }
536→
537→    // Case 2: single call — tools.cli.ts <toolName> '<jsonArgs>'
538→    const parsed = parseToolsCliCall(cmd);
539→    if (!parsed) continue;
540→
541→    let parsedArgs: Record<string, unknown> = {};
542→    try {
543→      parsedArgs = JSON.parse(parsed.argsJson);
544→    } catch { /* leave empty */ }
545→
546→    const resultJson = extractJsonFromResultText(entry.resultText);
547→
548→    prismCalls.push({
549→      seq: entry.seq,
550→      toolName: parsed.toolName,
551→      parsedArgs,
552→      resultJson,
553→    });
554→  }
555→
556→  const annotated: AnnotatedFinding[] = [];
557→  let totalEvidence = 0;
558→  let verifiedCount = 0;
559→  const suspects: Array<{ findingId: string; reason: string }> = [];
560→  const partiallyVerified: Array<{ findingId: string; reason: string }> = [];
561→
562→  for (const finding of findings) {
563→    const annotatedEvidences: AnnotatedEvidence[] = [];
564→    let findingHasUnverified = false;
565→
566→    for (const ev of finding.evidence) {
567→      totalEvidence++;
568→      // Find a matching prism call in the ledger
569→      const match = prismCalls.find(pc =>
570→        pc.toolName === ev.tool &&
571→        argsSubsetMatch(ev.args, pc.parsedArgs),
572→      );
573→
574→      if (!match) {
575→        annotatedEvidences.push({
576→          ...ev,
577→          verified: false,
578→          digestChecked: false,
579→          notVerifiedReason: `No ledger call found for tool=${ev.tool} with matching args: ${JSON.stringify(ev.args)}`,
580→        });
581→        findingHasUnverified = true;
582→      } else {
583→        verifiedCount++;
584→        // Spot-check digest
585→        let digestChecked = false;
586→        let digestOk = false;
587→        if (match.resultJson) {
588→          const check = spotCheckDigest(ev.resultDigest, match.resultJson);
589→          digestChecked = check.checked;
590→          digestOk = check.ok;
591→        }
592→
593→        annotatedEvidences.push({
594→          ...ev,
595→          verified: true,
596→          matchedLedgerSeq: match.seq,
597→          digestChecked,
598→          // Note: digest mismatch does NOT flip verified — human reviews suspects
599→          ...(digestChecked && !digestOk
600→            ? { notVerifiedReason: 'Digest numbers could not be matched in real result (possible rounding or fabrication — review manually)' }
601→            : {}),
602→        });
603→      }
604→    }
605→
606→    // DR-21: only flag as SUSPECT (likely fabrication) when EVERY piece of
607→    // evidence fails to match the ledger. A finding with some verified evidence
608→    // stands on that evidence; a single unmatched auxiliary query (often an
609→    // imprecisely-recalled nested-arg call) is a partial gap, not fabrication.
610→    const verifiedInFinding = annotatedEvidences.filter(ae => ae.verified).length;
611→    const allUnverified = verifiedInFinding === 0 && annotatedEvidences.length > 0;
612→    if (allUnverified) {
613→      const unverifiedTools = annotatedEvidences
614→        .map(ae => `${ae.tool}(${JSON.stringify(ae.args)})`)
615→        .join(', ');
616→      suspects.push({
617→        findingId: finding.id,
618→        reason: `NO evidence matched the ledger (likely fabricated): ${unverifiedTools}`,
619→      });
620→    } else if (findingHasUnverified) {
621→      partiallyVerified.push({
622→        findingId: finding.id,
623→        reason: `${verifiedInFinding}/${annotatedEvidences.length} evidence verified; unmatched: ` +
624→          annotatedEvidences.filter(ae => !ae.verified).map(ae => ae.tool).join(', '),
625→      });
626→    }
627→
628→    annotated.push({
629→      ...finding,
630→      evidence: annotatedEvidences,
631→    });
632→  }
633→
634→  const unverifiedCount = totalEvidence - verifiedCount;
635→  const findingsWithAllEvidenceVerified = annotated.filter(
636→    f => f.evidence.every(ae => ae.verified),
637→  ).length;
638→
639→  return {
640→    annotated,
641→    summary: {
642→      totalFindings: findings.length,
643→      totalEvidence,
644→      verifiedEvidence: verifiedCount,
645→      unverifiedEvidence: unverifiedCount,
646→      findingsWithAllEvidenceVerified,
647→      suspects,
648→      partiallyVerified,
649→    },
650→  };
651→}
