653→// ─────────────────────────────────────────────
654→// runPrismExplore — main entry point
655→// ─────────────────────────────────────────────
656→
657→export async function runPrismExplore(
658→  opts: RunPrismExploreOpts = {},
659→): Promise<ExploreRunResult> {
660→  const runId = opts.runId ?? 'unity-outside-stressmove';
661→  const config = getConfig();
662→
663→  // Resolve repo root robustly: this file is at web/server/prism/, so ../../.. from __dirname
664→  const repoRoot = path.resolve(__dirname, '../../..');
665→
666→  // Resolve outputDir. Default: archive each run under a timestamped subdir so
667→  // history is preserved (never overwritten) — serves as corpus / gold-set seed (F4).
668→  // A stable `latest` copy is also maintained for convenience.
669→  const stamp = new Date().toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19);
670→  const outputDir = opts.outputDir
671→    ? path.resolve(repoRoot, opts.outputDir)
672→    : path.join(repoRoot, 'web', 'data', 'prism-out', runId, stamp);
673→
674→  // Ensure outputDir exists
675→  fs.mkdirSync(outputDir, { recursive: true });
676→
677→  const ledgerPath = path.join(outputDir, 'ledger.json');
678→  const findingsPath = path.join(outputDir, 'findings.json');
679→  const dataRequestsPath = path.join(outputDir, 'data-requests.json');
680→  const verdictPath = path.join(outputDir, 'verdict.json');
681→  const exploreResultPath = path.join(outputDir, 'explore-result.json');
682→
683→  // Read and substitute prompt template
684→  const promptTemplatePath = path.join(__dirname, 'prompts', 'explore-prompt.txt');
685→  if (!fs.existsSync(promptTemplatePath)) {
686→    return makeError(runId, ledgerPath, findingsPath, `Prompt template not found: ${promptTemplatePath}`);
687→  }
688→
689→  let promptText = fs.readFileSync(promptTemplatePath, 'utf-8');
690→  // Use POSIX (forward-slash) path for OUTPUT_DIR so the LLM's Write calls work cross-platform
691→  const outputDirPosix = toPosix(outputDir);
692→  promptText = promptText.replace(/\{\{RUN_ID\}\}/g, runId);
693→  promptText = promptText.replace(/\{\{OUTPUT_DIR\}\}/g, outputDirPosix);
694→  // F8: frame-budget verdict basis. Default 16.67ms (60fps) per aoe-watch-spec deviceTier default.
695→  const frameBudgetMs = opts.frameBudgetMs ?? 16.67;
696→  const targetFps = Math.round(1000 / frameBudgetMs);
697→  promptText = promptText.replace(/\{\{FRAME_BUDGET_MS\}\}/g, String(frameBudgetMs));
698→  promptText = promptText.replace(/\{\{TARGET_FPS\}\}/g, String(targetFps));
699→  promptText = promptText.replace(/\{\{MEMORY_INJECTION\}\}/g, formatMemoryForPrompt());
700→
701→  // Resolve CLI
702→  const provider = opts.cliProvider ?? 'codebuddy';
703→  const { command: cliCommand, resolved } = resolveCliExecutable(provider, config.cliPaths?.[provider]);
704→
705→  if (!resolved) {
706→    return makeError(runId, ledgerPath, findingsPath, cliUnavailableHint(provider));
707→  }
708→
709→  const buildArgs = CLI_PROVIDERS[provider];
710→  if (!buildArgs) {
711→    return makeError(runId, ledgerPath, findingsPath, `Unknown CLI provider: ${provider}`);
712→  }
713→  const args = buildArgs(promptText);
714→
715→  console.log(`[explore] Spawning ${provider} CLI (${cliCommand})...`);
716→  console.log(`[explore] runId=${runId}, outputDir=${outputDirPosix}`);
717→
718→  const ledger: LedgerEntry[] = [];
719→  let toolCallSeq = 0;
720→  // Pending tool_use entries awaiting their tool_result (matched by position in stream order)
721→  const pendingToolUses: LedgerEntry[] = [];
722→
723→  const timeoutMs = opts.timeoutMs ?? 20 * 60 * 1000;
724→
725→  return new Promise<ExploreRunResult>((resolve) => {
726→    let settled = false;
727→    let jsonBuffer = '';
728→
729→    const child = spawnCliProcess(cliCommand, args, {
730→      cwd: config.skillProjectPath,
731→      env: process.env,
732→      windowsHide: true,
733→      stdio: 'pipe',
734→    });
735→
736→    // Pipe the prompt via stdin (Windows .cmd wrappers truncate long prompts
737→    // passed as positional args; stdin avoids that trap). `-p` with no value
738→    // makes the CLI read the prompt from stdin.
739→    try {
740→      child.stdin?.write(promptText);
741→      child.stdin?.end();
742→    } catch (e: any) {
743→      console.error(`[explore] stdin write failed: ${e?.message || e}`);
744→    }
745→
746→    const doResolve = (result: ExploreRunResult) => {
747→      if (!settled) {
748→        settled = true;
749→        resolve(result);
750→      }
751→    };
752→
753→    const timeoutHandle = setTimeout(() => {
754→      if (child.exitCode === null) {
755→        child.kill('SIGTERM');
756→      }
757→      // Write whatever ledger we have so far
758→      writeLedger(ledgerPath, ledger);
759→      doResolve(makeError(runId, ledgerPath, findingsPath, `Exploration timed out after ${timeoutMs}ms`));
760→    }, timeoutMs);
761→
762→    child.stdout?.on('data', (data: Buffer) => {
763→      jsonBuffer += data.toString();
764→      const lines = jsonBuffer.split('\n');
765→      jsonBuffer = lines.pop() || '';
766→
767→      for (const line of lines) {
768→        const trimmed = line.trim();
769→        if (!trimmed) continue;
770→        let event: Record<string, unknown>;
771→        try {
772→          event = JSON.parse(trimmed);
773→        } catch {
774→          // Non-JSON line — log it but continue
775→          console.log(`[explore:raw] ${trimmed.slice(0, 200)}`);
776→          continue;
777→        }
778→
779→        handleExploreStreamEvent(event, ledger, pendingToolUses, (seq, name, input) => {
780→          toolCallSeq = seq;
781→          console.log(`[explore:tool #${seq}] ${name}: ${JSON.stringify(input).slice(0, 180)}`);
782→        });
783→      }
784→    });
785→
786→    child.stderr?.on('data', (data: Buffer) => {
787→      const text = data.toString().trim();
788→      if (text) {
789→        console.error(`[explore:stderr] ${text.slice(0, 300)}`);
790→      }
791→    });
792→
793→    child.on('error', (err) => {
794→      clearTimeout(timeoutHandle);
795→      writeLedger(ledgerPath, ledger);
796→      doResolve(makeError(runId, ledgerPath, findingsPath, `CLI spawn error: ${err.message}`));
797→    });
798→
799→    child.on('close', (code) => {
800→      clearTimeout(timeoutHandle);
801→      writeLedger(ledgerPath, ledger);
802→
803→      if (code !== 0) {
804→        doResolve(makeError(runId, ledgerPath, findingsPath, `CLI exited with code ${code}`));
805→        return;
806→      }
807→
808→      // Read findings.json and data-requests.json written by the LLM
809→      let findings: Finding[];
810→      let dataRequests: DataRequest[];
811→
812→      try {
813→        const findingsText = fs.readFileSync(findingsPath, 'utf-8');
814→        findings = JSON.parse(findingsText) as Finding[];
815→      } catch (e) {
816→        doResolve(makeError(runId, ledgerPath, findingsPath,
817→          `Failed to read/parse findings.json: ${(e as Error).message}. ` +
818→          `The LLM may not have written the file or wrote invalid JSON.`));
819→        return;
820→      }
821→
822→      try {
823→        const drText = fs.readFileSync(dataRequestsPath, 'utf-8');
824→        dataRequests = JSON.parse(drText) as DataRequest[];
825→      } catch {
826→        // data-requests.json is optional — default to empty
827→        dataRequests = [];
828→        console.warn('[explore] data-requests.json missing or invalid; defaulting to []');
829→      }
830→
831→      // Read verdict.json (F8 overall verdict) — optional
832→      let verdict: Record<string, unknown> | null = null;
833→      try {
834→        verdict = JSON.parse(fs.readFileSync(verdictPath, 'utf-8')) as Record<string, unknown>;
835→      } catch {
836→        console.warn('[explore] verdict.json missing or invalid; verdict = null');
837→      }
838→
839→      // Verify evidence
840→      const { annotated, summary } = verifyFindings(findings, ledger);
841→
842→      const result: ExploreRunResult = {
843→        success: true,
844→        runId,
845→        findings,
846→        dataRequests,
847→        verdict,
848→        meta: {
849→          toolCallCount: toolCallSeq,
850→          rounds: undefined,
851→          notes: [`ledger has ${ledger.length} entries`],
852→        },
853→        ledgerPath,
854→        findingsPath,
855→        verification: summary,
856→        annotatedFindings: annotated,
857→      };
858→
859→      // Write explore-result.json for inspection
860→      fs.writeFileSync(exploreResultPath, JSON.stringify(result, null, 2), 'utf-8');
861→      console.log(`[explore] Done. findings=${findings.length} dataRequests=${dataRequests.length} toolCalls=${toolCallSeq}`);
862→      console.log(`[explore] Verification: verified=${summary.verifiedEvidence}/${summary.totalEvidence} suspects=${summary.suspects.length}`);
863→
864→      // BK-3: auto-aggregate DataRequests into the pool (capability loop auto-turns).
865→      // Fire-and-forget; failure here must not fail the exploration.
866→      try {
867→        const collector = path.join(repoRoot, 'web', 'server', 'prism', 'collect-datarequests.ts');
868→        const child = spawn(process.execPath, ['--import', 'tsx', collector], {
869→          cwd: path.join(repoRoot, 'web'), stdio: 'ignore', windowsHide: true, detached: false,
870→        });
871→        child.on('error', () => { /* ignore */ });
872→      } catch { /* ignore */ }
873→
874→      // M3-C: sediment DataRequests into persistent brain capabilities/ (incremental, never clear).
875→      try {
876→        const persisted = persistDataRequestsToMemory(dataRequests, { runId });
877→        if (persisted > 0) {
878→          console.log(`[explore] Persisted ${persisted} DataRequest(s) to capabilities memory`);
879→        }
880→      } catch (e) {
881→        console.warn(`[explore] Failed to persist DataRequests to memory: ${(e as Error).message}`);
882→      }
883→
884→      doResolve(result);
885→    });
886→  });
887→}
