889→// ─────────────────────────────────────────────
890→// Stream-json event handler
891→// ─────────────────────────────────────────────
892→
893→function handleExploreStreamEvent(
894→  event: Record<string, unknown>,
895→  ledger: LedgerEntry[],
896→  pendingToolUses: LedgerEntry[],
897→  onToolUse: (seq: number, name: string, input: Record<string, unknown>) => void,
898→): void {
899→  const type = event.type as string;
900→
901→  if (type === 'assistant') {
902→    const content = (event.message as Record<string, unknown>)?.content as unknown[];
903→    if (!Array.isArray(content)) return;
904→
905→    for (const block of content) {
906→      const b = block as Record<string, unknown>;
907→      if (b.type === 'tool_use') {
908→        const seq = ledger.length + 1;
909→        const name = (b.name as string) ?? 'unknown';
910→        const input = (b.input as Record<string, unknown>) ?? {};
911→
912→        const entry: LedgerEntry = { seq, name, input, resultText: '' };
913→        ledger.push(entry);
914→        pendingToolUses.push(entry);
915→
916→        onToolUse(seq, name, input);
917→      }
918→    }
919→  }
920→
921→  if (type === 'user') {
922→    const content = (event.message as Record<string, unknown>)?.content as unknown[];
923→    if (!Array.isArray(content)) return;
924→
925→    for (const item of content) {
926→      const r = item as Record<string, unknown>;
927→      if (r.type === 'tool_result') {
928→        const textContent = (r.content as unknown[])?.[0] as Record<string, unknown> | undefined;
929→        const text = (textContent?.text as string) ?? '';
930→        // Attach to the oldest unresolved tool_use
931→        const pending = pendingToolUses.shift();
932→        if (pending) {
933→          pending.resultText = text;
934→        }
935→      }
936→    }
937→  }
938→}
