900→// ─────────────────────── CLI entry ───────────────────────
901→
902→function getFlag(name: string): string | undefined {
903→  const i = process.argv.indexOf(name);
904→  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : undefined;
905→}
906→
907→async function main(): Promise<void> {
908→  const dir = getFlag('--dir') ?? 'data/prism-out/unity-outside-stressmove';
909→
910→  // Require narrative.json — do NOT fall back to findings.json
911→  const narrativePath = path.join(dir, 'narrative.json');
912→  if (!fs.existsSync(narrativePath)) {
913→    console.error(`[render-html] ERROR: narrative.json not found at ${narrativePath}`);
914→    console.error('[render-html] This renderer requires narrative.json (NarrativeReport shape). Run the narrative stage first.');
915→    process.exit(1);
916→  }
917→
918→  let narrative: NarrativeReport;
919→  try {
920→    narrative = JSON.parse(fs.readFileSync(narrativePath, 'utf-8')) as NarrativeReport;
921→  } catch (e) {
922→    console.error(`[render-html] ERROR: failed to parse narrative.json — ${(e as Error).message}`);
923→    process.exit(1);
924→  }
925→
926→  // DR-44 A2: provenance 强制校验——非 LLM 产出的 narrative.json 拒绝渲染。
927→  // 脚本拼的 narrative.json（无 narrativeProvenance 或 generatedBy !== 'LLM'）会被拦截，
928→  // 强制走 narrative LLM 阶段。
929→  if (
930→    !narrative.narrativeProvenance ||
931→    narrative.narrativeProvenance.generatedBy !== 'LLM'
932→  ) {
933→    const actual = narrative.narrativeProvenance?.generatedBy ?? 'missing';
934→    console.error(
935→      `[render-html] ERROR: narrative.json 的 narrativeProvenance.generatedBy 不是 'LLM'（实际：${actual}）。` +
936→        `脚本拼的 narrative.json 会被拒绝渲染——必须走 narrative LLM 阶段（DR-44 A2）。`,
937→    );
938→    process.exit(1);
939→  }
940→
941→  // Optional verdict.json for numeric metrics
942→  let verdict: Verdict | null = null;
943→  const verdictPath = path.join(dir, 'verdict.json');
944→  if (fs.existsSync(verdictPath)) {
945→    try {
946→      verdict = JSON.parse(fs.readFileSync(verdictPath, 'utf-8')) as Verdict;
947→    } catch {
948→      console.warn('[render-html] verdict.json found but failed to parse — metric strip will show "—"');
949→    }
950→  }
951→
952→  const dbPath = getFlag('--db');
953→  console.log(`[render-html] dir=${dir}  runId=${narrative.runId}  rating=${narrative.rating}`);
954→  console.log(`[render-html] sections=${narrative.sections.length}  topConclusions=${narrative.topConclusions.length}`);
955→
956→  const treesByItemKey = await requeryTrees(narrative, dbPath);
957→
958→  const html = renderHTML({ narrative, verdict, treesByItemKey });
959→
960→  const outPath = path.join(dir, 'report.html');
961→  fs.writeFileSync(outPath, html, 'utf-8');
962→
963→  const fileSizeKB = (fs.statSync(outPath).size / 1024).toFixed(1);
964→  console.log(`\n[render-html] Written: ${outPath}`);
965→  console.log(`[render-html] Size: ${fileSizeKB} KB`);
966→  console.log(`[render-html] Call-trees re-queried: ${treesByItemKey.size}`);
967→}
968→
969→main().catch(e => {
970→  console.error('[render-html] Fatal:', e);
971→  process.exit(1);
972→});
