2447→export function querySchedState(
2448→  _db: Database.Database | null | undefined,
2449→  args: QuerySchedStateArgs
2450→): QuerySchedStateResult {
2451→  const run = loadPerfettoRun(args);
2452→  const sched = asRecord(run.perfetto.threadsSched ?? run.summary.threadsSched);
2453→  const needle = args.thread?.toLowerCase();
2454→  const sortBy = args.sortBy ?? 'runningPct';
2455→  const topN = Math.min(args.topN ?? 20, 50);
2456→
2457→  let rows = Object.entries(sched).map(([name, raw]) => {
2458→    const r = asRecord(raw);
2459→    return {
2460→      name,
2461→      count: asNumber(r.count),
2462→      runningPct: asNumber(r.runningPct),
2463→      runnablePct: asNumber(r.runnablePct),
2464→      sleepingPct: asNumber(r.sleepingPct),
2465→      totalNs: asNumber(r.totalNs),
2466→    };
2467→  });
2468→
2469→  if (needle) rows = rows.filter(r => r.name.toLowerCase().includes(needle));
2470→  rows.sort((a, b) => {
2471→    if (sortBy === 'name') return a.name.localeCompare(b.name);
2472→    return (b[sortBy] ?? 0) - (a[sortBy] ?? 0);
2473→  });
2474→
2475→  return {
2476→    data: {
2477→      available: rows.length > 0,
2478→      window: getPerfettoProfileWindow(run),
2479→      totalThreads: rows.length,
2480→      threads: rows.slice(0, topN),
2481→    },
2482→    provenance: perfettoProvenance('querySchedState', args, run),
2483→  };
2484→}
