2579→function findChoreographerFrame(run: LoadedPerfettoRun): Record<string, unknown> | null {
2580→  const coreFrames = Array.isArray(run.core.frame) ? run.core.frame : [];
2581→  const fromCore = coreFrames.find(f => asRecord(f).frameDefinition === 'choreographer');
2582→  if (fromCore) return asRecord(fromCore);
2583→  const summaryFrames = Array.isArray(run.summary.frame) ? run.summary.frame : [];
2584→  const fromSummary = summaryFrames.find(f => asRecord(f).frameDefinition === 'choreographer');
2585→  if (fromSummary) return asRecord(fromSummary);
2586→  const nested = asRecord(run.summary.frame).choreographer;
2587→  return isRecord(nested) ? nested : null;
2588→}
2589→
2590→function findPlayerLoopFrame(run: LoadedPerfettoRun): Record<string, unknown> | null {
2591→  const coreFrames = Array.isArray(run.core.frame) ? run.core.frame : [];
2592→  const fromCore = coreFrames.find(f => asRecord(f).frameDefinition === 'playerloop');
2593→  if (fromCore) return asRecord(fromCore);
2594→  const summaryFrames = Array.isArray(run.summary.frame) ? run.summary.frame : [];
2595→  const fromSummary = summaryFrames.find(f => asRecord(f).frameDefinition === 'playerloop');
2596→  return fromSummary ? asRecord(fromSummary) : null;
2597→}
