2813→export function getPerfettoCallTree(
2814→  _db: Database.Database | null | undefined,
2815→  args: GetPerfettoCallTreeArgs
2816→): PerfettoCallTreeQueryResult {
2817→  const run = loadPerfettoRun(args);
2818→  const rawTrees = run.perfetto.callTrees ?? run.summary.callTrees;
2819→  const callTrees = Array.isArray(rawTrees) ? rawTrees.map(asRecord) : [];
2820→
2821→  if (callTrees.length === 0) {
2822→    return {
2823→      data: {
2824→        available: false,
2825→        reason: 'Perfetto callTrees is empty in the source profile; no synthetic call tree was created.',
2826→        callTrees: [],
2827→      },
2828→      provenance: perfettoProvenance('getPerfettoCallTree', args, run),
2829→    };
2830→  }
2831→
2832→  const selected = args.thread
2833→    ? callTrees.filter(t => String(t.thread ?? '').toLowerCase().includes(args.thread!.toLowerCase()))
2834→    : callTrees;
2835→
2836→  if (selected.length === 0) {
2837→    return {
2838→      data: {
2839→        available: false,
2840→        reason: `Perfetto callTrees exists but no tree matched thread "${args.thread}"; no synthetic call tree was created.`,
2841→        callTrees: [],
2842→      },
2843→      provenance: perfettoProvenance('getPerfettoCallTree', args, run),
2844→    };
2845→  }
2846→
2847→  const maxDepth = Math.min(args.maxDepth ?? 8, 20);
2848→  const topChildren = Math.min(args.topChildren ?? 8, 30);
2849→  const minTotalPct = args.minTotalPct ?? 0;
2850→  const prunedTrees = selected.map(tree => {
2851→    const root = asRecord(tree.root);
2852→    return {
2853→      ...tree,
2854→      root: prunePerfettoCallTreeNode(root, 0, maxDepth, topChildren, minTotalPct),
2855→    };
2856→  });
2857→
2858→  return {
2859→    data: {
2860→      available: true,
2861→      callTrees: prunedTrees,
2862→      hotPath: buildPerfettoHotPath(asRecord(asRecord(prunedTrees[0]).root)),
2863→    },
2864→    provenance: perfettoProvenance('getPerfettoCallTree', args, run),
2865→  };
2866→}
