2901→  const throttlingLevel = typeof throttling.level === 'string' ? throttling.level : undefined;
2902→  const throttlingSuspected = throttlingLevel === 'suspected' || system.cpuThrottled === true;
2903→  const runningPct = asNumber(schedEntry.runningPct);
2904→  const runnablePct = asNumber(schedEntry.runnablePct);
2905→  const signals: string[] = [];
