3020→export function queryCallTreeSubtree(
3021→  _db: Database.Database | null | undefined,
3022→  args: QueryCallTreeSubtreeArgs
3023→): QueryCallTreeSubtreeResult {
3024→  const run = loadPerfettoRun(args);
3025→  const minTotalPct = args.minTotalPct ?? 1.0;
3026→  const topN = Math.min(args.topN ?? 20, 200);
3027→  const includeSubtree = args.includeSubtree !== false;
3028→  const pattern = args.pattern?.toLowerCase();
3029→  const businessOnly = args.businessOnly === true;
3030→
3031→  let rows = collectCallTreeFlatNodes(run);
3032→  if (pattern) rows = rows.filter(r => r.name.toLowerCase().includes(pattern));
3033→  if (businessOnly) rows = rows.filter(r => r.layer === 'business');
3034→  rows = rows.filter(r => (r.totalPct ?? 0) >= minTotalPct);
3035→  rows.sort((a, b) => (b.totalMs ?? 0) - (a.totalMs ?? 0));
3036→  const totalNodes = rows.length;
3037→  const trimmed = rows.slice(0, topN).map(r => {
3038→    const out: QueryCallTreeSubtreeRow = {
3039→      name: r.name,
3040→      totalMs: r.totalMs,
3041→      totalPct: r.totalPct,
3042→      count: r.count,
3043→      avgMs: r.avgMs,
3044→      layer: r.layer,
3045→      depth: r.depth,
3046→      parentChain: r.parentChain,
3047→    };
3048→    if (includeSubtree) {
3049→      out.subtreeTotalMs = r.subtreeTotalMs;
3050→      out.subtreeTotalPct = r.subtreeTotalPct;
3051→    }
3052→    return out;
3053→  });
3054→
3055→  return {
3056→    data: {
3057→      available: trimmed.length > 0,
3058→      totalNodes,
3059→      rows: trimmed,
3060→    },
3061→    provenance: perfettoProvenance('queryCallTreeSubtree', args, run),
3062→  };
3063→}
