3274→export function queryOffCpuAttribution(
3275→  _db: Database.Database | null | undefined,
3276→  args: QueryOffCpuAttributionArgs
3277→): QueryOffCpuAttributionResult {
3278→  const run = loadPerfettoRun(args);
3279→  const thread = args.thread ?? 'UnityMain';
3280→  const sched = asRecord(run.perfetto.threadsSched ?? run.summary.threadsSched);
3281→  const schedEntry = asRecord(
3282→    sched[thread] ??
3283→      Object.entries(sched).find(([name]) => name.toLowerCase().includes(thread.toLowerCase()))?.[1]
3284→  );
3285→  // Prefer expanded offCpuAttribution; fall back to offCpuReasons (same object after WT-022)
3286→  const offCpu = asRecord(
3287→    run.perfetto.offCpuAttribution ??
3288→      run.summary.offCpuAttribution ??
3289→      run.perfetto.offCpuReasons ??
3290→      run.summary.offCpuReasons
3291→  );
3292→  const window = getPerfettoProfileWindow(run);
3293→  const durMs = asNumber(window?.durMs);
3294→
3295→  const sleepingPct =
3296→    asNumber(offCpu.sleepingPct) ?? asNumber(schedEntry.sleepingPct) ?? null;
3297→  const runnablePct =
3298→    asNumber(offCpu.runnablePct) ?? asNumber(schedEntry.runnablePct) ?? null;
3299→  const runningPct =
3300→    asNumber(schedEntry.runningPct) ??
3301→    (sleepingPct != null
3302→      ? roundNumber(100 - sleepingPct - (runnablePct ?? 0), 2) ?? null
3303→      : null);
3304→  const totalOffCpuMs = asNumber(offCpu.totalOffCpuMs) ?? null;
3305→  const rawByState = Array.isArray(offCpu.byState) ? offCpu.byState : [];
3306→  const byState = rawByState.map(row => {
3307→    const r = asRecord(row);
3308→    return {
3309→      state: typeof r.state === 'string' ? r.state : String(r.state ?? 'Unknown'),
3310→      totalMs: asNumber(r.totalMs) ?? null,
3311→      count: asNumber(r.count) ?? null,
3312→      pctOfOffCpu: asNumber(r.pctOfOffCpu) ?? null,
3313→    };
3314→  });
3315→  const note =
3316→    (typeof offCpu.note === 'string' && offCpu.note) ||
3317→    'offCpuReasons / wait-slice coverage derived from summary + callTree; no synthetic blocked-reason rows.';
3318→
3319→  const flat = collectCallTreeFlatNodes(run);
3320→  const waitSlices = flat
3321→    .filter(n => isWaitSliceName(n.name))
3322→    .sort((a, b) => (b.totalMs ?? 0) - (a.totalMs ?? 0))
3323→    .map(n => ({
3324→      name: n.name,
3325→      totalMs: n.totalMs,
3326→      totalPct: n.totalPct,
3327→      count: n.count,
3328→      avgMs: n.avgMs,
3329→      parentChain: n.parentChain,
3330→    }));
3331→
3332→  const waitSliceTotalMs =
3333→    waitSlices.length > 0
3334→      ? roundNumber(
3335→          waitSlices.reduce((sum, s) => sum + (s.totalMs ?? 0), 0),
3336→          3
3337→        ) ?? null
3338→      : null;
3339→  const sleepingMs =
3340→    totalOffCpuMs != null && sleepingPct != null
3341→      ? roundNumber((totalOffCpuMs * sleepingPct) / 100, 1) ?? null
3342→      : durMs != null && sleepingPct != null
3343→        ? roundNumber((durMs * sleepingPct) / 100, 3) ?? null
3344→        : null;
3345→  const coveragePct =
3346→    sleepingMs != null && sleepingMs > 0 && waitSliceTotalMs != null
3347→      ? roundNumber((waitSliceTotalMs / sleepingMs) * 100, 2) ?? null
3348→      : null;
3349→
3350→  return {
3351→    data: {
3352→      available: byState.length > 0 || sleepingPct != null || waitSlices.length > 0,
3353→      thread,
3354→      runningPct,
3355→      sleepingPct,
3356→      runnablePct,
3357→      totalOffCpuMs,
3358→      byState,
3359→      waitSlices,
3360→      sleepingMs,
3361→      waitSliceTotalMs,
3362→      coveragePct,
3363→      note,
