2702→export function queryCpuFreq(
2703→  _db: Database.Database | null | undefined,
2704→  args: QueryCpuFreqArgs
2705→): QueryCpuFreqResult {
2706→  const run = loadPerfettoRun(args);
2707→  const system = asRecord(run.core.system ?? run.summary.system);
2708→  const throttling = asRecord(run.perfetto.throttling ?? run.summary.throttling);
2709→  const perCpuRaw = Array.isArray(throttling.perCpu) ? throttling.perCpu.map(asRecord) : [];
2710→  const perCpu: QueryCpuFreqPerCpuRow[] = perCpuRaw.map(r => ({
2711→    cpu: asNumber(r.cpu) ?? -1,
2712→    avgMhz: asNumber(r.avgMhz) ?? null,
2713→    maxMhz: asNumber(r.maxMhz) ?? null,
2714→    cpuinfoMaxMhz: asNumber(r.cpuinfoMaxMhz) ?? null,
2715→    reachPct: asNumber(r.reachPct) ?? null,
2716→    reachVsCpuinfoPct: asNumber(r.reachVsCpuinfoPct) ?? null,
2717→  })).filter(r => r.cpu >= 0);
2718→  const avgMhz = asNumber(system.cpuFreqAvgMhz);
2719→  const level = typeof throttling.level === 'string' ? throttling.level : undefined;
2720→  const cpuThrottled = typeof system.cpuThrottled === 'boolean' ? system.cpuThrottled : undefined;
2721→  const evidence = Array.isArray(throttling.evidence)
2722→    ? throttling.evidence.filter((v): v is string => typeof v === 'string')
2723→    : [];
2724→
2725→  // Generic cluster split by CPU index (0-3 / 4-6 / ≥7) — no SoC name hardcoding.
2726→  const small = perCpu.filter(r => r.cpu <= 3);
2727→  const mid = perCpu.filter(r => r.cpu >= 4 && r.cpu <= 6);
2728→  const big = perCpu.filter(r => r.cpu >= 7);
2729→
2730→  return {
2731→    data: {
2732→      available: avgMhz != null || perCpu.length > 0,
2733→      avgMhz,
2734→      cpuThrottled,
2735→      throttlingLevel: level,
2736→      throttlingSuspected: level === 'suspected' || cpuThrottled === true,
2737→      bigCoreReachPct: asNumber(throttling.bigCoreReachPct),
2738→      perCpu,
2739→      clusterSummary: {
2740→        small: summarizeCpuCluster(small),
2741→        mid: summarizeCpuCluster(mid),
2742→        big: summarizeCpuCluster(big),
2743→      },
2744→      evidence,
2745→    },
2746→    provenance: perfettoProvenance('queryCpuFreq', args, run),
2747→  };
2748→}
