2772→function prunePerfettoCallTreeNode(
2773→  node: Record<string, unknown>,
2774→  depth: number,
2775→  maxDepth: number,
2776→  topChildren: number,
2777→  minTotalPct: number
2778→): Record<string, unknown> {
2779→  const children = Array.isArray(node.children) ? node.children.map(asRecord) : [];
2780→  const prunedChildren = depth >= maxDepth
2781→    ? []
2782→    : children
2783→        .filter(child => (asNumber(child.totalPct) ?? 0) >= minTotalPct)
2784→        .sort((a, b) => (asNumber(b.totalMs) ?? asNumber(b.totalPct) ?? 0) - (asNumber(a.totalMs) ?? asNumber(a.totalPct) ?? 0))
2785→        .slice(0, topChildren)
2786→        .map(child => prunePerfettoCallTreeNode(child, depth + 1, maxDepth, topChildren, minTotalPct));
2787→  return { ...node, children: prunedChildren };
2788→}
