2790→function buildPerfettoHotPath(root: Record<string, unknown>): Array<{ name: string; totalMs?: number; totalPct?: number; selfMs?: number; selfPct?: number }> {
2791→  const pathRows: Array<{ name: string; totalMs?: number; totalPct?: number; selfMs?: number; selfPct?: number }> = [];
2792→  let current: Record<string, unknown> | undefined = root;
2793→  while (current) {
2794→    pathRows.push({
2795→      name: typeof current.name === 'string' ? current.name : '(unknown)',
2796→      totalMs: asNumber(current.totalMs),
2797→      totalPct: asNumber(current.totalPct),
2798→      selfMs: asNumber(current.selfMs),
2799→      selfPct: asNumber(current.selfPct),
2800→    });
2801→    const childNodes: Record<string, unknown>[] = Array.isArray(current.children)
2802→      ? current.children.map(asRecord)
2803→      : [];
2804→    current = childNodes.reduce((best: Record<string, unknown> | undefined, child: Record<string, unknown>) => {
2805→      const childScore = asNumber(child.totalMs) ?? asNumber(child.totalPct) ?? 0;
2806→      const bestScore = best ? asNumber(best.totalMs) ?? asNumber(best.totalPct) ?? 0 : -Infinity;
2807→      return childScore > bestScore ? child : best;
2808→    }, undefined);
2809→  }
2810→  return pathRows;
2811→}
